import React from 'react';
import { useNavigate } from 'react-router-dom';
import TransitionAlerts from '../../components/minimalAlert';

const ProductInfoSection = () => {
    const navigate = useNavigate();
    const [showAlert, setShowAlert] = React.useState(false);
    const [alertMessage, setAlertMessage] = React.useState("");
    const alertTimeoutRef = React.useRef(null);
    const [itemCount, setItemCount] = React.useState(0);
    const [product, setProduct] = React.useState(null);

    React.useEffect(() => {
        const storedProduct = localStorage.getItem('selectedProduct');
        if (storedProduct) {
            setProduct(JSON.parse(storedProduct));
        }
    }, []);

    const triggerAlert = (msg) => {
        setAlertMessage(msg);
        setShowAlert(true);
        if (alertTimeoutRef.current) {
            clearTimeout(alertTimeoutRef.current);
        }
        alertTimeoutRef.current = setTimeout(() => setShowAlert(false), 3000);
    };

    const handleAddToCart = (e) => {
        e.preventDefault();

        const session = sessionStorage.getItem('session');
        if (!session) {
            navigate('/');
            return;
        }

        setItemCount(1);
        triggerAlert("Item added successfully");

        const userData = JSON.parse(session);
        const newCount = (userData.cartCount || 0) + 1;
        sessionStorage.setItem('session', JSON.stringify({ ...userData, cartCount: newCount }));
        window.dispatchEvent(new Event('cartUpdated'));
    };

    const handleIncrement = (e) => {
        e.preventDefault();
        setItemCount(prev => prev + 1);
        triggerAlert("Item added successfully");

        const session = sessionStorage.getItem('session');
        if (session) {
            const userData = JSON.parse(session);
            const newCount = (userData.cartCount || 0) + 1;
            sessionStorage.setItem('session', JSON.stringify({ ...userData, cartCount: newCount }));
            window.dispatchEvent(new Event('cartUpdated'));
        }
    };

    const handleDecrement = (e) => {
        e.preventDefault();
        setItemCount(prev => {
            const count = prev - 1;
            return count >= 0 ? count : 0;
        });
        triggerAlert("Item removed successfully");

        const session = sessionStorage.getItem('session');
        if (session) {
            const userData = JSON.parse(session);
            const newCount = Math.max((userData.cartCount || 0) - 1, 0);
            sessionStorage.setItem('session', JSON.stringify({ ...userData, cartCount: newCount }));
            window.dispatchEvent(new Event('cartUpdated'));
        }
    };

    return (
        <>
            <TransitionAlerts open={showAlert} onClose={() => setShowAlert(false)} message={alertMessage} />
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 items-start mb-16">
